1937		/**
1938		 * Start a run from a user or custom message. The session counts as busy from here on, so
1939		 * messages sent while before_agent_start handlers run are queued into this run instead of
1940		 * starting another, and an abort requested meanwhile aborts the run as soon as it exists.
1941		 * @param onStarted Called once the run's messages are prepared, before the first request.
1942		 */
1943		private async _startRun(trigger: BeforeAgentStartTrigger, onStarted?: () => void): Promise<void> {
1944			this._isAgentRunActive = true;
1945			this._agentRunAbortRequested = false;
1946			let messages: AgentMessage[];
1947			try {
1948				messages = await this._prepareRun(trigger);
1949			} catch (error) {
1950				this._isAgentRunActive = false;
1951				this._flushPendingBashMessages();
1952				this._flushPendingCustomMessages();
1953				this._resolveIdleWaitIfIdle();
1954				throw error;
1955			}
1956			// Messages held while the run was starting go before its starting messages, as they would
1957			// have while idle. No run exists yet, so they cannot split a tool call from its result.
1958			this._flushPendingBashMessages();
1959			this._flushPendingCustomMessages();
1960			onStarted?.();
1961	
1962			// Compaction before the prompt may have scheduled a retry; the new prompt replaces it.
1963			this._failedResponse = undefined;
1964			this._recordSelection();
1965			// The run records the loadout in the transcript; restored tools that did not register by now
1966			// are dropped, so a tool that never registers does not stay pending.
1967			this._pendingToolNames.clear();
1968			try {
1969				await this.agent.prompt(messages);
1970				while (!this._agentRunAbortRequested) {
1971					if (await this._handlePostAgentRun()) {
1972						if (this._agentRunAbortRequested) break;
1973						await this.agent.continue();
1974						continue;
1975					}
1976					if (this._agentRunAbortRequested || !(await this._runBeforeSettleBoundary())) break;
1977					if (this._agentRunAbortRequested) break;
1978					await this.agent.continue();
1979				}
1980			} finally {
1981				if (this._agentRunAbortRequested) this._finishCancelledRetry();
1982				this._failedResponse = undefined;
1983				this._runSystemPromptOptions = undefined;
1984				this._flushPendingBashMessages();
1985				this._flushPendingCustomMessages();
1986				await this._emitAgentSettled();
1987			}
1988		}
