1990		/**
1991		 * Prepare a run and return its starting messages: compact first when needed, emit
1992		 * before_agent_start, apply the run's prompt options and tool loadout, and build the starting
1993		 * message followed by pending nextTurn messages (consumed here) and handler messages, with a
1994		 * system patch first when the prompt changed.
1995		 */
1996		private async _prepareRun(trigger: BeforeAgentStartTrigger): Promise<AgentMessage[]> {
1997			// Check if we need to compact before sending (catches aborted responses).
1998			// The starting message is sent below, so do not call agent.continue() here.
1999			const lastAssistant = this._findLastAssistantMessage();
2000			if (lastAssistant) {
2001				await this._checkCompaction(lastAssistant, false);
2002			}
2003	
2004			const selectedToolsBefore = this._baseSystemPromptOptions.selectedTools;
2005			const result = await this._extensionRunner.emitBeforeAgentStart(trigger, this._baseSystemPromptOptions);
2006			// Handlers may edit event.systemPromptOptions.selectedTools or call setActiveTools(),
2007			// which updates the live loadout instead. An explicit edit wins; otherwise the live
2008			// loadout is authoritative, so a setActiveTools() call is not undone here.
2009			const handlerEditedTools =
2010				result.systemPromptOptions.selectedTools.length !== selectedToolsBefore.length ||
2011				result.systemPromptOptions.selectedTools.some((name, index) => name !== selectedToolsBefore[index]);
2012			if (!handlerEditedTools) result.systemPromptOptions.selectedTools = this.getActiveToolNames();
2013	
2014			const messages: AgentMessage[] = [];
2015			if (trigger.messageType === "custom") {
2016				messages.push(trigger.message);
2017			} else {
2018				// Normalize images after before_agent_start so extension-driven model selection
2019				// determines the resize profile used for the request and history.
2020				const normalized = await this._normalizePromptImages(trigger.images);
2021				const text =
2022					normalized.hints.length > 0 ? `${trigger.prompt}\n\n${normalized.hints.join("\n")}` : trigger.prompt;
2023				messages.push({
2024					role: "user",
2025					content: [{ type: "text", text }, ...normalized.images],
2026					timestamp: Date.now(),
2027				});
2028			}
2029			// Inject any pending "nextTurn" messages as context alongside the starting message
2030			messages.push(...this._pendingNextTurnMessages);
2031			this._pendingNextTurnMessages = [];
2032			for (const msg of result.messages) {
2033				messages.push({
2034					role: "custom",
2035					customType: msg.customType,
2036					// Untyped extensions can pass null/missing content; normalize at ingestion.
2037					content: msg.content ?? [],
2038					display: msg.display,
2039					details: msg.details,
2040					timestamp: Date.now(),
2041				});
2042			}
2043			const updateMessage = this._preparePromptAndToolLoadout(result.systemPromptOptions);
2044			this._runSystemPromptOptions = result.systemPromptOptions;
2045			if (updateMessage) messages.unshift(updateMessage);
2046			return messages;
2047		}
