2049		private async _handlePostAgentRun(): Promise<boolean> {
2050			const message = this._lastAssistantMessage;
2051			this._lastAssistantMessage = undefined;
2052			if (this._agentRunAbortRequested) {
2053				this._finishCancelledRetry();
2054				return false;
2055			}
2056			if (!message) return this.agent.hasQueuedMessages();
2057	
2058			if (this._isRetryableError(message) && (await this._prepareRetry(message))) {
2059				if (this._agentRunAbortRequested) this._finishCancelledRetry();
2060				this._failedResponse = message;
2061				return !this._agentRunAbortRequested;
2062			}
2063			if (this._agentRunAbortRequested) {
2064				this._finishCancelledRetry();
2065				return false;
2066			}
2067	
2068			if (message.stopReason === "error" && this._retryAttempt > 0) {
2069				this._emit({
2070					type: "auto_retry_end",
2071					success: false,
2072					attempt: this._retryAttempt,
2073					finalError: message.errorMessage,
2074				});
2075				this._retryAttempt = 0;
2076			}
2077	
2078			if (await this._checkCompaction(message)) {
2079				return !this._agentRunAbortRequested;
2080			}
2081	
2082			// The low-level loop drains both queues before agent_end. Messages queued by
2083			// agent_end handlers require a fresh run before pre-settlement handlers fire.
2084			return !this._agentRunAbortRequested && this.agent.hasQueuedMessages();
2085		}
