2087		private async _runBeforeSettleBoundary(): Promise<boolean> {
2088			if (!this._extensionRunner.hasHandlers("agent_before_settle")) return this.agent.hasQueuedMessages();
2089			this._isBeforeSettle = true;
2090			this._abortDuringBeforeSettle = false;
2091			try {
2092				const result = await this._extensionRunner.emitBoundary(
2093					{ type: "agent_before_settle", outcome: this._lastActivityOutcome },
2094					(entries) => this._buildBoundaryContext(entries, "agent_before_settle"),
2095				);
2096				this._commitBoundaryDrafts(result.entries);
2097				this._flushPendingCustomMessages();
2098				const finalContext = this._buildBoundaryContext([], "agent_before_settle");
2099				if (this._abortDuringBeforeSettle) return false;
2100				const shouldContinue = result.continue || this.agent.hasQueuedMessages();
2101				if (shouldContinue && !finalContext.canContinue) {
2102					if (result.continue) this._reportInvalidBoundaryContinuation("agent_before_settle");
2103					return false;
2104				}
2105				return shouldContinue;
2106			} finally {
2107				this._isBeforeSettle = false;
2108			}
2109		}
